#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────
#
# Step 4 of docs/backlog/plan-escaneo-operar-a-mano.md: the Telegram bot and
# the Klaviyo list the unlock needs, saved to .dev.vars (wrangler dev) and as
# secrets of the jeanmanzo Worker. Run from the repo root:
#   bash scripts/setup-escaneo.sh

cd "$(dirname "$0")/.."
ENV_FILE=".dev.vars"
# Keep in step with KLAVIYO_REVISION in worker/index.ts.
KLAVIYO_REVISION="2026-07-15"
KLAVIYO_LIST_NAME="Escaneo operar a mano"
CF_SET=()

# json EXPR reads JSON on stdin and prints EXPR, evaluated with the parsed body as `d`.
json() { node -e "let s='';process.stdin.on('data',c=>s+=c).on('end',()=>{const d=JSON.parse(s);const v=($1);if(v!==undefined&&v!==null)console.log(v)})"; }

klaviyo() {
  curl -sSg "https://a.klaviyo.com/api/$1" \
    -H "Authorization: Klaviyo-API-Key $KLAVIYO_API_KEY" \
    -H "revision: $KLAVIYO_REVISION" \
    -H "accept: application/vnd.api+json" \
    -H "content-type: application/vnd.api+json" "${@:2}"
}

# set_cf_secret NAME VALUE uploads a secret to the jeanmanzo Worker.
set_cf_secret() {
  if printf '%s' "$2" | npx wrangler secret put "$1" >/dev/null 2>&1; then
    CF_SET+=("$1")
    printf '  %s✓ set%s Cloudflare secret %s\n' "$GREEN" "$RESET" "$1"
  else
    SKIPPED+=("Cloudflare secret $1 (npx wrangler secret put $1)")
    warn "no pude cargar $1 en Cloudflare; queda para hacerlo a mano"
  fi
}

TOTAL_STAGES=6

banner "Escaneo: Telegram, Klaviyo y Cloudflare"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Telegram: crear el bot"
say "El Worker te avisa por este bot cada vez que alguien desbloquea un Escaneo."
open_url "https://t.me/BotFather"
step "En el chat con @BotFather, escribe /newbot."
step "Nombre: el que quieras, por ejemplo Escaneo Jean."
step "Usuario: tiene que terminar en bot, por ejemplo escaneo_jeanmanzo_bot."
step "BotFather te responde con un token (algo como 123456:ABC-...). Cópialo."
ask_secret TELEGRAM_BOT_TOKEN "Pega el token:"
BOT_USER=$(curl -sS "https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/getMe" | json 'd.ok ? d.result.username : ""' || true)
if [[ -z "$BOT_USER" ]]; then
  warn "Telegram no reconoce ese token. Vuelve a correr el wizard y pégalo otra vez."
  exit 1
fi
printf '  %s✓%s bot @%s\n' "$GREEN" "$RESET" "$BOT_USER"
write_env TELEGRAM_BOT_TOKEN "$TELEGRAM_BOT_TOKEN"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Telegram: tu chat ID"
say "El bot solo puede escribirte si tú le escribes primero."
open_url "https://t.me/${BOT_USER}"
step "Toca Iniciar (Start) y mándale cualquier mensaje, por ejemplo hola."
pause "Cuando le hayas escrito, Enter."
TELEGRAM_CHAT_ID=$(curl -sS "https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/getUpdates" \
  | json 'd.ok ? (d.result.map(u => u.message && u.message.chat.id).filter(Boolean).pop() ?? "") : ""' || true)
if [[ -z "$TELEGRAM_CHAT_ID" ]]; then
  _current=$(_existing TELEGRAM_CHAT_ID || true)
  [[ -z "$_current" ]] && { warn "No veo tu mensaje. Escríbele al bot y vuelve a correr el wizard."; exit 1; }
  TELEGRAM_CHAT_ID="$_current"
fi
curl -sS -o /dev/null "https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage" \
  --data-urlencode "chat_id=${TELEGRAM_CHAT_ID}" \
  --data-urlencode "text=Listo. Aquí te llegan los Escaneos desbloqueados."
printf '  %s✓%s chat ID %s. Te mandé un mensaje de prueba.\n' "$GREEN" "$RESET" "$TELEGRAM_CHAT_ID"
write_env TELEGRAM_CHAT_ID "$TELEGRAM_CHAT_ID"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Klaviyo: API key privada"
say "Con esta clave el Worker guarda el contacto y lo suscribe a la lista."
open_url "https://www.klaviyo.com/settings/account/api-keys"
note "Si no abre ahí: Settings (abajo a la izquierda) → Account → API keys."
step "Clic en Create Private API Key."
step "Nombre: Escaneo jeanmanzo.com."
step "Elige Custom Key y dale Full Access solo a: Lists, Profiles, Events y Subscriptions."
step "Clic en Create y copia la clave (empieza con pk_). Solo se muestra una vez."
ask_secret KLAVIYO_API_KEY "Pega la API key:"
if ! klaviyo "lists/?fields[list]=name" | json 'd.data ? "ok" : ""' | grep -q ok; then
  warn "Klaviyo rechazó la clave o le falta el permiso de Lists. Créala otra vez y vuelve a correr el wizard."
  exit 1
fi
printf '  %s✓%s Klaviyo acepta la clave\n' "$GREEN" "$RESET"
write_env KLAVIYO_API_KEY "$KLAVIYO_API_KEY"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Klaviyo: la lista del Escaneo"
KLAVIYO_LIST_ID=$(klaviyo "lists/?fields[list]=name" -G --data-urlencode "filter=equals(name,\"${KLAVIYO_LIST_NAME}\")" \
  | json 'd.data && d.data[0] ? d.data[0].id : ""' || true)
if [[ -n "$KLAVIYO_LIST_ID" ]]; then
  say "Ya tienes la lista \"${KLAVIYO_LIST_NAME}\". Uso esa."
elif confirm "¿Creo la lista \"${KLAVIYO_LIST_NAME}\" en tu Klaviyo?"; then
  KLAVIYO_LIST_ID=$(klaviyo "lists/" -X POST \
    -d "{\"data\":{\"type\":\"list\",\"attributes\":{\"name\":\"${KLAVIYO_LIST_NAME}\"}}}" \
    | json 'd.data ? d.data.id : ""' || true)
  [[ -z "$KLAVIYO_LIST_ID" ]] && { warn "No pude crear la lista. Créala a mano en Lists & segments y vuelve a correr el wizard."; exit 1; }
else
  ask KLAVIYO_LIST_ID "Entonces pega el ID de la lista que quieras usar:"
fi
printf '  %s✓%s lista %s\n' "$GREEN" "$RESET" "$KLAVIYO_LIST_ID"
write_env KLAVIYO_LIST_ID "$KLAVIYO_LIST_ID"
say ""
say "Un ajuste a mano, para que no le llegue un email de confirmación a cada lead:"
open_url "https://www.klaviyo.com/lists"
step "Abre la lista \"${KLAVIYO_LIST_NAME}\" → Settings."
step "En Opt-in process elige Single opt-in y guarda."
note "La casilla de autorización del Escaneo ya cubre el consentimiento (Ley 1581)."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: cargar los secrets"
say "Los 4 valores ya están en .dev.vars para probar en local con pnpm worker:dev."
say "Ahora los subo al Worker jeanmanzo, para producción."
warn "Cada secret publica una versión nueva del Worker con el código que ya está en vivo."
if confirm "¿Los subo?"; then
  for key in TELEGRAM_BOT_TOKEN TELEGRAM_CHAT_ID KLAVIYO_API_KEY KLAVIYO_LIST_ID; do
    set_cf_secret "$key" "${!key}"
  done
else
  SKIPPED+=("Cloudflare secrets: vuelve a correr el wizard (Enter conserva lo guardado)")
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: la base de datos"
say "El desbloqueo guarda cuándo pasó y el país en D1. Falta aplicar esa migración en producción."
note "Solo agrega 2 columnas a la tabla results. No borra nada."
if confirm "¿Aplico las migraciones pendientes de D1 en producción?"; then
  if npx wrangler d1 migrations apply escaneo --remote; then
    printf '  %s✓%s D1 al día\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("D1: npx wrangler d1 migrations apply escaneo --remote")
  fi
else
  SKIPPED+=("D1: npx wrangler d1 migrations apply escaneo --remote")
fi
pause

finish
(( ${#CF_SET[@]} )) && note "set ${#CF_SET[@]} Cloudflare secret(s): ${CF_SET[*]}"
printf '\n'
